import React from "react";
import { useStatus } from "../contexts/StatusContext";

interface StatCardProps {
  title: string;
  value: string | number;
  change?: string;
  changeType?: "increase" | "decrease" | "neutral";
  icon: React.ReactNode;
  color: "primary" | "success" | "warning" | "error" | "secondary";
}

const StatCard: React.FC<StatCardProps> = ({
  title,
  value,
  change,
  changeType = "neutral",
  icon,
  color,
}) => {
  const colorClasses = {
    primary: "gradient-primary",
    success: "gradient-success",
    warning: "gradient-warning",
    error: "gradient-error",
    secondary: "gradient-secondary",
  };

  const changeColorClasses = {
    increase: "text-success-600 bg-success-50",
    decrease: "text-error-600 bg-error-50",
    neutral: "text-secondary-600 bg-secondary-50",
  };

  return (
    <div className="bg-white rounded-xl shadow-sm p-6 card-hover">
      <div className="flex items-center">
        <div className={`p-3 rounded-lg ${colorClasses[color]} text-white`}>
          {icon}
        </div>
        <div className="ml-4 flex-1">
          <p className="text-sm font-medium text-secondary-600 mb-1">{title}</p>
          <p className="text-2xl font-bold text-secondary-900">{value}</p>
          {change && (
            <div
              className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium mt-2 ${changeColorClasses[changeType]}`}
            >
              {changeType === "increase" && (
                <svg
                  className="w-3 h-3 mr-1"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M7 17l9.2-9.2M17 17V7H7"
                  />
                </svg>
              )}
              {changeType === "decrease" && (
                <svg
                  className="w-3 h-3 mr-1"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M17 7l-9.2 9.2M7 7v10h10"
                  />
                </svg>
              )}
              {change}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

interface ProgressBarProps {
  label: string;
  value: number;
  max: number;
  color: "primary" | "success" | "warning" | "error";
}

const ProgressBar: React.FC<ProgressBarProps> = ({
  label,
  value,
  max,
  color,
}) => {
  const percentage = Math.min((value / max) * 100, 100);

  const colorClasses = {
    primary: "bg-primary-500",
    success: "bg-success-500",
    warning: "bg-warning-500",
    error: "bg-error-500",
  };

  return (
    <div className="mb-4">
      <div className="flex justify-between text-sm text-secondary-600 mb-1">
        <span>{label}</span>
        <span>
          {value}/{max}
        </span>
      </div>
      <div className="w-full bg-secondary-200 rounded-full h-2">
        <div
          className={`h-2 rounded-full transition-all duration-300 ${colorClasses[color]}`}
          style={{ width: `${percentage}%` }}
        />
      </div>
    </div>
  );
};

interface ClientStatusProps {
  clients: any[];
}

const ClientStatus: React.FC<ClientStatusProps> = ({ clients }) => {
  const statusCounts = clients.reduce((acc, client) => {
    const status = client.connection_status || "disconnected";
    acc[status] = (acc[status] || 0) + 1;
    return acc;
  }, {});

  const statusItems = [
    {
      status: "connected",
      label: "Online",
      color: "success",
      count: statusCounts.connected || 0,
    },
    {
      status: "disconnected",
      label: "Offline",
      color: "error",
      count: statusCounts.disconnected || 0,
    },
    {
      status: "connecting",
      label: "Connecting",
      color: "warning",
      count: statusCounts.connecting || 0,
    },
    {
      status: "error",
      label: "Error",
      color: "error",
      count: statusCounts.error || 0,
    },
  ];

  return (
    <div className="bg-white rounded-xl shadow-sm p-6">
      <h3 className="text-lg font-semibold text-secondary-900 mb-4">
        Client Status
      </h3>
      <div className="space-y-3">
        {statusItems.map(
          (item) =>
            item.count > 0 && (
              <div
                key={item.status}
                className="flex items-center justify-between"
              >
                <div className="flex items-center">
                  <div
                    className={`w-3 h-3 rounded-full mr-3 ${
                      item.color === "success"
                        ? "status-online"
                        : item.color === "warning"
                          ? "status-warning"
                          : "status-offline"
                    }`}
                  />
                  <span className="text-sm text-secondary-600">
                    {item.label}
                  </span>
                </div>
                <span className="text-sm font-medium text-secondary-900">
                  {item.count}
                </span>
              </div>
            ),
        )}
        {clients.length === 0 && (
          <div className="text-center py-4">
            <p className="text-sm text-secondary-500">No clients connected</p>
          </div>
        )}
      </div>
    </div>
  );
};

export const Dashboard: React.FC = () => {
  const { state } = useStatus();

  const formatUptime = (seconds: number): string => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    return `${hours}h ${minutes}m`;
  };

  const formatBytes = (bytes: number): string => {
    const sizes = ["Bytes", "KB", "MB", "GB"];
    if (bytes === 0) return "0 Bytes";
    const i = Math.floor(Math.log(bytes) / Math.log(1024));
    return Math.round((bytes / Math.pow(1024, i)) * 100) / 100 + " " + sizes[i];
  };

  // Calculate derived metrics
  const totalClients = state.clients.length;
  const connectedClients = state.clients.filter(
    (c) => c.connection_status === "connected",
  ).length;
  const busyWorkers = state.clients.filter(
    (c) => c.worker_status === "busy",
  ).length;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold text-secondary-900 mb-2">
          Dashboard
        </h1>
        <p className="text-secondary-600">
          Real-time monitoring of your TetraCore StreamHub instance
        </p>
      </div>

      {/* Status Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard
          title="Total Clients"
          value={totalClients}
          change={
            connectedClients > 0 ? `${connectedClients} online` : "None online"
          }
          changeType={connectedClients > 0 ? "increase" : "neutral"}
          color="primary"
          icon={
            <svg
              className="w-6 h-6"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197m13.5-9a2.5 2.5 0 11-5 0 2.5 2.5 0 015 0z"
              />
            </svg>
          }
        />

        <StatCard
          title="Tasks Processed"
          value={state.taskStats?.completed_tasks || 0}
          change={
            state.taskStats?.pending_tasks
              ? `${state.taskStats.pending_tasks} pending`
              : "No pending tasks"
          }
          changeType="neutral"
          color="success"
          icon={
            <svg
              className="w-6 h-6"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M9 5H7a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 4h.01M9 12h.01M9 16h.01M13 8h3m-3 4h3m-3 4h3"
              />
            </svg>
          }
        />

        <StatCard
          title="System Uptime"
          value={
            state.health?.uptime ? formatUptime(state.health.uptime) : "N/A"
          }
          change="Running smoothly"
          changeType="increase"
          color="secondary"
          icon={
            <svg
              className="w-6 h-6"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"
              />
            </svg>
          }
        />

        <StatCard
          title="Memory Usage"
          value={
            state.metrics?.system?.memory_usage
              ? `${Math.round(state.metrics.system.memory_usage)}%`
              : "N/A"
          }
          change={
            state.metrics?.system?.memory_usage
              ? state.metrics.system.memory_usage > 80
                ? "High usage"
                : "Normal"
              : "No data"
          }
          changeType={
            state.metrics?.system?.memory_usage &&
            state.metrics.system.memory_usage > 80
              ? "decrease"
              : "neutral"
          }
          color={
            state.metrics?.system?.memory_usage &&
            state.metrics.system.memory_usage > 80
              ? "warning"
              : "primary"
          }
          icon={
            <svg
              className="w-6 h-6"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M9 3v2m6-2v2M9 19v2m6-2v2M5 9H3m2 6H3m18-6h-2m2 6h-2M7 19h10a2 2 0 002-2V7a2 2 0 00-2-2H7a2 2 0 00-2 2v10a2 2 0 002 2zM9 9h6v6H9V9z"
              />
            </svg>
          }
        />
      </div>

      {/* Main Content Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* System Health */}
        <div className="lg:col-span-2">
          <div className="bg-white rounded-xl shadow-sm p-6">
            <h3 className="text-lg font-semibold text-secondary-900 mb-4">
              System Health
            </h3>

            {state.health ? (
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-sm text-secondary-600 mb-1">Status</p>
                    <div className="flex items-center">
                      <div
                        className={`w-3 h-3 rounded-full mr-2 ${
                          state.health.status === "healthy"
                            ? "status-online"
                            : "status-offline"
                        }`}
                      />
                      <span className="text-sm font-medium capitalize">
                        {state.health.status}
                      </span>
                    </div>
                  </div>
                  <div>
                    <p className="text-sm text-secondary-600 mb-1">Version</p>
                    <span className="text-sm font-medium">
                      {state.health.version}
                    </span>
                  </div>
                </div>

                <div>
                  <p className="text-sm text-secondary-600 mb-3">Components</p>
                  <div className="grid grid-cols-2 gap-2">
                    {Object.entries(state.health.components).map(
                      ([component, status]) => (
                        <div
                          key={component}
                          className="flex items-center justify-between py-2 px-3 bg-secondary-50 rounded-lg"
                        >
                          <span className="text-xs font-medium text-secondary-700 capitalize">
                            {component.replace("_", " ")}
                          </span>
                          <div
                            className={`w-2 h-2 rounded-full ${status ? "status-online" : "status-offline"}`}
                          />
                        </div>
                      ),
                    )}
                  </div>
                </div>

                {state.metrics && (
                  <div>
                    <p className="text-sm text-secondary-600 mb-3">
                      Resource Usage
                    </p>
                    <div className="space-y-3">
                      <ProgressBar
                        label="CPU Usage"
                        value={Math.round(state.metrics.system.cpu_usage)}
                        max={100}
                        color={
                          state.metrics.system.cpu_usage > 80
                            ? "error"
                            : state.metrics.system.cpu_usage > 60
                              ? "warning"
                              : "success"
                        }
                      />
                      <ProgressBar
                        label="Memory Usage"
                        value={Math.round(state.metrics.system.memory_usage)}
                        max={100}
                        color={
                          state.metrics.system.memory_usage > 80
                            ? "error"
                            : state.metrics.system.memory_usage > 60
                              ? "warning"
                              : "success"
                        }
                      />
                      <ProgressBar
                        label="Disk Usage"
                        value={Math.round(state.metrics.system.disk_usage)}
                        max={100}
                        color={
                          state.metrics.system.disk_usage > 80
                            ? "error"
                            : state.metrics.system.disk_usage > 60
                              ? "warning"
                              : "success"
                        }
                      />
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-sm text-secondary-600 mb-1">Status</p>
                    <div className="flex items-center">
                      <div className="w-3 h-3 rounded-full mr-2 bg-secondary-300" />
                      <span className="text-sm font-medium text-secondary-500">
                        Connecting...
                      </span>
                    </div>
                  </div>
                  <div>
                    <p className="text-sm text-secondary-600 mb-1">Version</p>
                    <span className="text-sm font-medium text-secondary-500">
                      Loading...
                    </span>
                  </div>
                </div>

                <div>
                  <p className="text-sm text-secondary-600 mb-3">Components</p>
                  <div className="grid grid-cols-2 gap-2">
                    <div className="flex items-center justify-between py-2 px-3 bg-secondary-50 rounded-lg">
                      <span className="text-xs font-medium text-secondary-700">
                        Redis
                      </span>
                      <div className="w-2 h-2 rounded-full bg-secondary-300" />
                    </div>
                    <div className="flex items-center justify-between py-2 px-3 bg-secondary-50 rounded-lg">
                      <span className="text-xs font-medium text-secondary-700">
                        Client Manager
                      </span>
                      <div className="w-2 h-2 rounded-full bg-secondary-300" />
                    </div>
                    <div className="flex items-center justify-between py-2 px-3 bg-secondary-50 rounded-lg">
                      <span className="text-xs font-medium text-secondary-700">
                        Task Router
                      </span>
                      <div className="w-2 h-2 rounded-full bg-secondary-300" />
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Client Status */}
        <div>
          <ClientStatus clients={state.clients} />
        </div>
      </div>

      {/* Task Queue Overview */}
      {state.taskStats && (
        <div className="bg-white rounded-xl shadow-sm p-6">
          <h3 className="text-lg font-semibold text-secondary-900 mb-4">
            Task Queue Overview
          </h3>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="text-center">
              <p className="text-2xl font-bold text-primary-600">
                {state.taskStats.total_tasks}
              </p>
              <p className="text-sm text-secondary-600">Total Tasks</p>
            </div>
            <div className="text-center">
              <p className="text-2xl font-bold text-warning-600">
                {state.taskStats.pending_tasks}
              </p>
              <p className="text-sm text-secondary-600">Pending</p>
            </div>
            <div className="text-center">
              <p className="text-2xl font-bold text-primary-600">
                {state.taskStats.processing_tasks}
              </p>
              <p className="text-sm text-secondary-600">Processing</p>
            </div>
            <div className="text-center">
              <p className="text-2xl font-bold text-success-600">
                {state.taskStats.completed_tasks}
              </p>
              <p className="text-sm text-secondary-600">Completed</p>
            </div>
          </div>

          {state.taskStats.average_processing_time > 0 && (
            <div className="mt-4 pt-4 border-t border-secondary-200">
              <p className="text-sm text-secondary-600">
                Average Processing Time:{" "}
                <span className="font-medium">
                  {Math.round(state.taskStats.average_processing_time)}ms
                </span>
              </p>
            </div>
          )}
        </div>
      )}

      {/* Recent Alerts */}
      {state.alerts.length > 0 && (
        <div className="bg-white rounded-xl shadow-sm p-6">
          <h3 className="text-lg font-semibold text-secondary-900 mb-4">
            Recent Alerts
          </h3>
          <div className="space-y-3">
            {state.alerts.slice(0, 5).map((alert) => (
              <div
                key={alert.id}
                className={`p-3 rounded-lg border-l-4 ${
                  alert.type === "error"
                    ? "bg-error-50 border-error-500"
                    : alert.type === "warning"
                      ? "bg-warning-50 border-warning-500"
                      : alert.type === "success"
                        ? "bg-success-50 border-success-500"
                        : "bg-primary-50 border-primary-500"
                }`}
              >
                <div className="flex justify-between items-start">
                  <div>
                    <p className="text-sm font-medium text-secondary-900">
                      {alert.title}
                    </p>
                    <p className="text-xs text-secondary-600 mt-1">
                      {alert.message}
                    </p>
                  </div>
                  <span className="text-xs text-secondary-500">
                    {new Date(alert.timestamp).toLocaleTimeString()}
                  </span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Loading State */}
      {state.isLoading && (
        <div className="fixed bottom-4 right-4 bg-white rounded-lg shadow-lg p-4 flex items-center space-x-3">
          <div className="spinner w-5 h-5"></div>
          <span className="text-sm text-secondary-600">Updating data...</span>
        </div>
      )}

      {/* Error State */}
      {state.error && (
        <div className="fixed bottom-4 right-4 bg-error-50 border border-error-200 rounded-lg p-4 max-w-sm">
          <div className="flex items-start space-x-3">
            <svg
              className="w-5 h-5 text-error-500 mt-0.5"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
              />
            </svg>
            <div>
              <p className="text-sm font-medium text-error-900">
                Connection Error
              </p>
              <p className="text-xs text-error-700 mt-1">{state.error}</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
